svg.script:
(function () {
  var DUR = 8000;

var heroEl = document.getElementById('ib-hero-num');
var m1El = document.getElementById('ib-m-1');
function renderAt(p) {
  var s = Math.sin(2 * Math.PI * p);
  if (heroEl) {
    if (Math.abs(s) < 0.06) {
      heroEl.innerHTML = '100M<tspan fill="#2A93A1">+</tspan>';
    } else {
      var m = (100 + 12.4 * s).toFixed(1);
      heroEl.innerHTML = m + 'M<tspan fill="#2A93A1">+</tspan>';
    }
  }
  if (m1El) {
    if (Math.abs(s) < 0.06) {
      m1El.textContent = '10M+';
    } else {
      m1El.textContent = (10 + 0.8 * s).toFixed(1) + 'M+';
    }
  }
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
